from taf.internal.gnb.oam.coam.vdu.client.trs_licensed.v1 import (
    ApiClient,
    Configuration,
    IpTrafficCaptureApi,
    IpTrafficCaptureGenerateFileConfiguration,
    SshTunnelMgmtApi,
    ApiException
)

from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.m2m_interface_availability_checker import (
    m2m_interface_availability_check,
)
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.services.trs_licensed.http_client import TRSLicensedHttpClient


@auto_token_refresh(api_exception=ApiException)
class TRSLicensedV1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.ssh_tunnel_mgmt_api = SshTunnelMgmtApi(api_client)
        self.ip_traffic_capture_api = IpTrafficCaptureApi(api_client)
        self.local_client = TRSLicensedHttpClient(base_url=con_details.base_url,
                                                  connection_alias=con_details.alias)

    @m2m_interface_availability_check
    def config_ssh_tunnel(self, dist_name, operation, timeout=30):
        return self.local_client.config_ssh_tunnel(dist_name=dist_name, operation=operation, timeout=timeout)

    @m2m_interface_availability_check
    def get_ssh_tunnel_config(self, ssh_mode_type, timeout=30):
        return self.ssh_tunnel_mgmt_api.get_ssh_tunnel_port_get(ssh_module_type=ssh_mode_type, _request_timeout=timeout)

    @m2m_interface_availability_check
    def start_ip_traffic_capture(self, capture_type, measurement_point, plane_type, pod_names, timeout=30):
        self.local_client.start_ip_traffic_capture(capture_type=capture_type,
                                                   plane_type=plane_type,
                                                   pod_names=pod_names,
                                                   measurement_point=measurement_point,
                                                   timeout=timeout)

    @m2m_interface_availability_check
    def stop_ip_traffic_capture(self, timeout=30):
        self.local_client.stop_ip_traffic_capture(timeout=timeout)

    @m2m_interface_availability_check
    def abort_ip_traffic_capture(self, timeout=30):
        self.local_client.abort_ip_traffic_capture(timeout=timeout)

    @m2m_interface_availability_check
    def generate_ip_traffic_capture_files(self, credentials, timeout=30):
        credentials = IpTrafficCaptureGenerateFileConfiguration(credentials=credentials)
        return self.ip_traffic_capture_api.ip_traffic_capture_generate_post(ip_traffic_capture_generate_file_configuration=credentials,
                                                                            _request_timeout=timeout)

    @m2m_interface_availability_check
    def activate_file_upload_operation(self, timeout=30):
        return self.local_client.activate_file_upload_operation(timeout=timeout)

    @m2m_interface_availability_check
    def get_file_upload_operation(self, operation_id, timeout=30):
        return self.ip_traffic_capture_api.ip_traffic_capture_files_activate_upload_operation_id_get(operation_id=operation_id,
                                                                                                     _request_timeout=timeout)

    @m2m_interface_availability_check
    def delete_file_upload_operation(self, timeout=30):
        self.local_client.delete_file_upload_operation(timeout=timeout)

    @m2m_interface_availability_check
    def upload_ip_traffic_capture_file(self, operation_id, file_name, timeout=30):
        return self.ip_traffic_capture_api.ip_traffic_capture_upload_operation_id_file_name_get(operation_id=operation_id,
                                                                                                file_name=file_name,
                                                                                                _request_timeout=timeout)

    @m2m_interface_availability_check
    def get_ip_traffic_capture_status(self, timeout=30):
        return self.local_client.get_ip_traffic_capture_status(timeout=timeout)
